  "findings": [
    {
      "cwe_id": "CWE-639",
      "explanation": "The new epic_id query parameter is used to filter user stories by epic order without verifying that the requesting user has permission to view that epic. The code extracts epic_id from request.QUERY_PARAMS and passes it to attach_epic_order, which builds a raw SQL condition using the supplied epic_id directly, resulting in an IDOR where a user can supply any epic ID and retrieve ordering information for epics they may not have access to.",
      "evidence": [
        {
          "type": "code",
          "file": "taiga/projects/userstories/api.py",
          "lines": [102, 108],
          "content": "epic_id =  self.request.QUERY_PARAMS.get(\"epic\", None)\nqs = attach_extra_info(qs, user=self.request.user,\n                       include_attachments=include_attachments,\n                       include_tasks=include_tasks,\n                       epic_id=epic_id)"
        },
        {
          "type": "code",
          "file": "taiga/projects/userstories/utils.py",
          "lines": [131, 149],
          "content": "def attach_epic_order(queryset, epic_id, as_field=\"epic_order\"):\n    ...\n    sql = \"\"\"SELECT \"epics_relateduserstory\".\"order\" AS \"epic_order\"\n               FROM \"epics_relateduserstory\"\n              WHERE \"epics_relateduserstory\".\"user_story_id\" = {tbl}.id and\n                    \"epics_relateduserstory\".\"epic_id\" = {epic_id}\"\"\"\n    sql = sql.format(tbl=model._meta.db_table, epic_id=epic_id)\n    queryset = queryset.extra(select={as_field: sql})\n    return queryset"
        }
      ],
      "suggested_fix": "Validate that the epic_id belongs to an epic the user is allowed to view (e.g., check project membership or use existing permission filters) before passing it to attach_epic_order, and reject or ignore unauthorized epic_id values.",
      "file": "taiga/projects/userstories/api.py",
      "line": 102
    }
  ]
}

